/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormEventHandler(formStr(MarkupAutoSetup), FormEventType::Closing)]
public static void MarkupAutoSetup_OnClosing(xFormRun sender, FormEventArgs e)
{
    FormRun         formRun = sender;
    MarkupAutoTable markupAutoTable = formRun.dataSource(tableStr(MarkupAutoTable)).cursor();
    if(markupAutoTable.metIsGUPAutoCharge())
    {
        MarkupAutoTable::metProcessTrackChange(markupAutoTable.RecId, SysAppCRUDOperation::Update, METFormEditAction::Save);
    }
}
